(async()=>{
 const container=document.getElementById('admin-editor'),status=document.getElementById('admin-status');if(!container)return;
 const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');let content;
 const bookingLabels={mustafa:'Sheikh Mustafa Akhound',baghernejad:'Sheikh Mohammad Baghernejad',medical:'Medical guidance','mental-health':'Mental health & wellbeing','real-estate':'Real estate',legal:'Legal guidance','tax-finance':'Tax & financial guidance'};
 const field=(label,name,value,type='text')=>`<label>${label}<${type==='textarea'?'textarea':'input'} data-field="${name}" ${type!=='textarea'?`value="${esc(value)}"`:''}>${type==='textarea'?esc(value)+'</textarea>':''}</label>`;
 try{const response=await fetch('/api/admin/content');if(!response.ok)throw Error((await response.json()).error);content=await response.json();render();status.textContent="Ready to edit. Save your changes when finished.";}catch(e){status.textContent=e.message;}
 function imageField(item,type,i){return `<label>Image address<input data-field="image" value="${esc(item.image)}"></label><label>Upload a new photo<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${type}:${i}"></label><img class="admin-image" src="${esc(item.image)}" alt="Image preview">`;}
 function render(){container.innerHTML=`<h2>Homepage photo library</h2><p>Five photos appear at a time. The selection changes every Monday at midnight in Springfield. Edit the approved library below; photos are stored on this site, so Facebook login is not needed.</p><div class="admin-card-grid">${content.slides.map((s,i)=>`<article class="admin-card" data-slide="${i}"><h3>Slide ${i+1}</h3>${field('Small heading','kicker',s.kicker)}${field('Main heading · use a new line for emphasis','title',s.title,'textarea')}${field('Description','description',s.description,'textarea')}${imageField(s,'slide',i)}${field('Photo position on desktop','position',s.position)}${field('Photo position on phones','mobilePosition',s.mobilePosition)}${field('Main button text','primaryLabel',s.primary[0])}${field('Main button destination','primaryUrl',s.primary[1])}${field('Second button text','secondaryLabel',s.secondary[0])}${field('Second button destination','secondaryUrl',s.secondary[1])}</article>`).join('')}</div><h2>Learning thumbnails</h2><div class="admin-card-grid">${content.education.map((s,i)=>`<article class="admin-card" data-education="${i}"><h3>${['Guide Academy','Saturday Islamic School','Imam Sadiq Seminary','After School','Workshops'][i]}</h3>${imageField(s,'education',i)}${field('Photo description for accessibility','alt',s.alt)}</article>`).join('')}</div><h2>Koalendar appointment links</h2><p>Create booking pages in IAC’s Koalendar account, then paste each public booking link here. Leave a link blank until that consultant is ready.</p><div class="admin-card-grid">${Object.entries(bookingLabels).map(([id,label])=>`<article class="admin-card"><h3>${label}</h3><label>Koalendar booking link<input type="url" data-booking-editor="${id}" placeholder="https://koalendar.com/e/your-booking-page" value="${esc(content.bookings?.[id]||'')}"></label></article>`).join('')}</div><h2>Daily Shorts</h2><p>Four videos rotate daily from this list. Add video IDs from the IAC YouTube Shorts channel, one per line. A video ID is the final part of its link.</p><label>Shorts video IDs<textarea id="shorts-editor" rows="8">${esc(content.shorts.join('\n'))}</textarea></label><button class="button button-dark" type="button" id="save-content">Save website changes →</button>`;
 container.querySelectorAll('[data-upload]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;const note=status;note.textContent='Uploading image…';try{const r=await fetch('/api/admin/upload',{method:'POST',headers:{'content-type':file.type},body:file});const data=await r.json();if(!r.ok)throw Error(data.error);const card=input.closest('.admin-card');card.querySelector('[data-field="image"]').value=data.url;card.querySelector('img').src=data.url;note.textContent='Image uploaded. Save website changes to publish it.';}catch(e){note.textContent=e.message;}}));
 document.getElementById('save-content').addEventListener('click',async()=>{const button=document.getElementById('save-content');button.disabled=true;status.textContent='Saving…';try{const next=structuredClone(content);container.querySelectorAll('[data-slide]').forEach(card=>{const s=next.slides[Number(card.dataset.slide)];card.querySelectorAll('[data-field]').forEach(input=>{const k=input.dataset.field;if(k==='primaryLabel')s.primary[0]=input.value;else if(k==='primaryUrl')s.primary[1]=input.value;else if(k==='secondaryLabel')s.secondary[0]=input.value;else if(k==='secondaryUrl')s.secondary[1]=input.value;else s[k]=input.value;});});container.querySelectorAll('[data-education]').forEach(card=>card.querySelectorAll('[data-field]').forEach(input=>next.education[Number(card.dataset.education)][input.dataset.field]=input.value));next.bookings={};container.querySelectorAll('[data-booking-editor]').forEach(input=>next.bookings[input.dataset.bookingEditor]=input.value.trim());next.shorts=document.getElementById('shorts-editor').value.split(/\s+/).filter(Boolean);const response=await fetch('/api/admin/content',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(next)});const data=await response.json();if(!response.ok)throw Error(data.error);content=next;status.textContent='Saved. Website content and appointment links are updated.';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}});
 }
})();

(async()=>{
 const inbox=document.getElementById('requests-inbox'),status=document.getElementById('requests-status');if(!inbox)return;
 const esc=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
 async function load(){status.textContent='Loading service requests…';try{const response=await fetch('/api/admin/requests');const data=await response.json();if(!response.ok)throw Error(data.error);status.textContent=data.requests.length?`${data.requests.length} most recent requests. ${data.requests.filter(r=>r.status==='new').length} new.`:'No service requests yet.';inbox.innerHTML=data.requests.map(r=>`<article class="admin-card request-inbox-card"><div class="request-inbox-heading"><h3>${esc(r.service.replaceAll('-',' '))}</h3><span>${esc(r.id.slice(0,8).toUpperCase())} · ${esc(new Date(r.created_at).toLocaleString('en-US',{timeZone:'America/New_York'}))} ET</span></div><dl>${Object.entries(r.fields).filter(([key,v])=>!key.startsWith('_')&&v).map(([key,value])=>`<div><dt>${esc(key.replace(/([a-z])([A-Z])/g,'$1 $2'))}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${r.fields._attachments?.length?`<div class="request-attachments"><h4>Attached documents</h4>${r.fields._attachments.map(file=>`<a href="/api/admin/request-document?request=${encodeURIComponent(r.id)}&amp;file=${encodeURIComponent(file.id)}">${esc(file.label)} · ${esc(file.name)} (${Math.ceil(file.size/1024)} KB)</a>`).join('')}</div>`:''}<label>Status<select data-request-status="${esc(r.id)}">${['new','reviewed','closed'].map(s=>`<option value="${s}" ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join('');inbox.querySelectorAll('[data-request-status]').forEach(select=>select.addEventListener('change',async()=>{select.disabled=true;try{const response=await fetch('/api/admin/requests',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id:select.dataset.requestStatus,status:select.value})});if(!response.ok)throw Error((await response.json()).error);status.textContent='Request status saved.';}catch(e){status.textContent=e.message;}finally{select.disabled=false;}}));}catch(e){status.textContent=e.message||'Requests could not be loaded.';}}
 document.getElementById('refresh-requests').addEventListener('click',load);await load();
})();

(async()=>{
 const form=document.getElementById('gmail-connection-form');if(!form)return;
 const status=document.getElementById('email-connection-status'),feedback=document.getElementById('gmail-connection-feedback'),copy=document.getElementById('copy-gmail-code');
 try{const response=await fetch('/api/admin/email-delivery');const data=await response.json();if(!response.ok)throw Error(data.error);form.elements.url.value=data.url;status.textContent=data.connected?'Connected: new requests are emailed to iacdmv@gmail.com.':'Not connected yet. Complete the three steps below.';copy.disabled=!data.setupReady;}catch(e){status.textContent=e.message||'Mail setup could not load.';}
 copy.addEventListener('click',async()=>{copy.disabled=true;try{const response=await fetch('/api/admin/email-script');if(!response.ok)throw Error('Setup code could not load.');const code=await response.text();await navigator.clipboard.writeText(code);feedback.textContent='Setup code copied. Paste it into Code.gs in your private Google Apps Script project.';}catch(e){feedback.textContent='Use Download setup code, open the file as text, and copy it into Code.gs.';}finally{copy.disabled=false;}});
 form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;feedback.textContent='Checking Google’s authorization…';try{const response=await fetch('/api/admin/email-delivery',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({url:form.elements.url.value.trim()})});const data=await response.json();if(!response.ok)throw Error(data.error);status.textContent='Connected: new requests are emailed to iacdmv@gmail.com.';feedback.textContent='Gmail connected. New submissions and attachments will be emailed directly, without saving their contents in the request database.';}catch(e){feedback.textContent=e.message||'Could not connect Gmail. Check the deployment settings and try again.';}finally{button.disabled=false;}});
})();

(async()=>{
 const form=document.getElementById('square-connection-form');if(!form)return;
 const status=document.getElementById('square-connection-status'),feedback=document.getElementById('square-connection-feedback');
 const esc=s=>String(s||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
 const describe=d=>d.connected?`Connected to ${d.businessName} · ${d.mode==='production'?'Production: real payments':'Sandbox: test payments only'}`:'Square is not connected yet.';
 try{const response=await fetch('/api/admin/square');const data=await response.json();if(!response.ok)throw Error(data.error);status.textContent=describe(data);if(data.connected){form.elements.mode.value=data.mode;form.elements.appId.value=data.appId;form.elements.locationId.value=data.locationId;}form.querySelector('[type="submit"]').disabled=!data.setupReady;}catch(e){status.textContent=e.message;}
 form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;feedback.textContent='Checking the Square location…';try{const data=Object.fromEntries(new FormData(form));data.ratesConfirmed=form.elements.ratesConfirmed.checked;const response=await fetch('/api/admin/square',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error);form.elements.accessToken.value='';status.textContent=describe(result);feedback.textContent=result.mode==='production'?'Square connected. The hall rental form can now accept real payments.':'Square Sandbox connected. Review with test cards before switching to Production.';}catch(e){feedback.textContent=e.message;}finally{button.disabled=false;}});
 async function payments(){const box=document.getElementById('hall-payment-records');try{const r=await fetch('/api/admin/hall-payments');const d=await r.json();if(!r.ok)throw Error(d.error);box.innerHTML=d.payments.length?d.payments.map(p=>`<article class="admin-card"><strong>${esc(p.id.slice(0,8).toUpperCase())} · ${(p.amount/100).toLocaleString('en-US',{style:'currency',currency:'USD'})}</strong><p>${esc(p.status)} · ${esc(p.mode)} · ${esc(p.created_at)}${p.payment_id?` · Square payment ${esc(p.payment_id)}`:''}</p><p>${p.status==='paid'&&!p.notified?'Notification pending. Contact the customer through Square.':''}</p></article>`).join(''):'<p>No hall payments yet.</p>';}catch(e){box.textContent=e.message;}}
 document.querySelector('[data-refresh-payments]').addEventListener('click',payments);await payments();
})();
